(()=>{const priorAll=allShotReferences;allShotReferences=function(target){return priorAll(target).map(r=>{const ref=target.videoTailReferences?.[r.picture];if(target.pictureBindingOverrides?.[r.picture]?.source!=='previous_tail'||!ref)return r;const item={id:ref.id,url:ref.image_url,label:'上一分镜 '+ref.source_target_id+' 尾帧 · 本段起始画面'};return{...r,type:'scene',ref_id:ref.scene_id,name:'上一分镜 '+ref.source_target_id+' 尾帧',item,choices:{...r.choices,active:item.id,items:[item]}};});};
const previousPrompt=composeReferencePrompt;composeReferencePrompt=function(target,base){let prompt=previousPrompt(target,base);const selected=allShotReferences(target).filter(r=>r.enabled),tails=selected.map((r,i)=>({r,tag:'<Picture '+(i+1)+'>'})).filter(({r})=>target.pictureBindingOverrides?.[r.picture]?.source==='previous_tail');if(!tails.length)return prompt;const note='Opening continuity: use the preceding shot final frame for the opening composition, character positions, poses and lighting. Continue the specified actions from that state; this reference is not the ending frame.';return /detailed_description\s*:/i.test(prompt)?prompt.replace(/detailed_description\s*:/i,'detailed_description:\n'+note+'\n'):prompt+'\n'+note;};
const priorShots=shots;shots=function(){priorShots();const target=shotVideoTarget();if(!target)return;const list=data.shotScript?.hierarchical?data.shots:shotMode==='clips'?data.shotScript?.generation_clips||[]:data.shots,index=list.indexOf(target),previous=list[index-1],version=previous&&selectedShotVideo(previous);for(const [i,card]of [...document.querySelectorAll('.shot-reference-card')].entries()){const r=allShotReferences(target)[i];if(!r)continue;const label=document.createElement('label');label.textContent='参考图来源';const select=document.createElement('select');select.setAttribute('aria-label',r.picture+' 参考图来源');select.innerHTML='<option value="library">人物 / 场景素材库</option><option value="previous_tail" '+(!version?.video_url?'disabled':'')+'>上一分镜视频尾帧'+(previous?' · '+(previous.shot_id||previous.clip_id):'（没有上一分镜）')+(!version?.video_url&&previous?'（视频未完成）':'')+'</option>';select.value=target.pictureBindingOverrides?.[r.picture]?.source||'library';label.append(select);card.querySelector('b')?.after(label);const useTail=select.value==='previous_tail';if(useTail){for(const attr of ['data-ref-type','data-ref-resource','data-shot-ref'])card.querySelector('['+attr+']')?.closest('label')?.style.setProperty('display','none');const versions=card.querySelector('[data-shot-ref]');if(versions)versions.style.display='none';const note=document.createElement('p');note.className='subtle';note.textContent='已作为本段起始画面参考，实际视频提示词已同步。';card.append(note);}select.onchange=async()=>{target.pictureBindingOverrides??={};const o=target.pictureBindingOverrides[r.picture]??={type:r.type,ref_id:r.ref_id,enabled:r.enabled};if(select.value==='library'){o.source='library';if(o.library_binding){Object.assign(o,o.library_binding);delete o.library_binding;}else delete o.usage;delete target.pictureSelections?.[r.picture];save();render();return;}if(!version?.video_url){toast('请先完成上一分镜视频');return;}select.disabled=true;try{const sceneId=target.scene_id||(data.scenes?.[0]?.id)||'CONTINUITY';const frame=await frontFetch('/api/video-frame',{project_id:data.project_id,scene_id:sceneId,video_id:version.id||version.job_id});target.videoTailReferences??={};target.videoTailReferences[r.picture]=frame;if(o.source!=='previous_tail')o.library_binding={type:o.type,ref_id:o.ref_id,usage:o.usage};Object.assign(o,{source:'previous_tail',type:'scene',ref_id:sceneId,enabled:true,usage:'Use this previous-shot final frame as the opening-frame visual guide for the current video. Continue its composition, character positions, poses, environment and lighting; use separate character references to preserve identity.'});delete target.pictureSelections?.[r.picture];save();render();toast('已选入上一段尾帧，并作为本段起始画面参考');}catch(e){toast(e.message);select.disabled=false;select.value='library';}};}};render();})();
